cat > main.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"time"
)

const (
	VersionString   = "miniserve 0.32.0"
	AppDescription  = "For when you really just want to serve some files over HTTP right now!"
	VersionBanner   = "miniserve v0.32.0"
	DefaultPort     = 8080
	MiniserveEnvKey = "MINISERVE_PATH"
)

func progName() string {
	if len(os.Args) == 0 {
		return "miniserve"
	}
	return filepath.Base(os.Args[0])
}

func logErr(msg string) {
	ts := time.Now().UTC().Format("Mon, 02 Jan 2006 15:04:05 -0700")
	fmt.Fprintf(os.Stderr, "%s [ERROR] %s\n", ts, msg)
}

func logWarn(msg string) {
	ts := time.Now().UTC().Format("Mon, 02 Jan 2006 15:04:05 -0700")
	fmt.Fprintf(os.Stderr, "%s [WARN] %s\n", ts, msg)
}

func logInfo(msg string) {
	ts := time.Now().UTC().Format("Mon, 02 Jan 2006 15:04:05 -0700")
	fmt.Fprintf(os.Stderr, "%s [INFO] %s\n", ts, msg)
}

func main() {
	opts, err := parseArgs(os.Args[1:])
	if err != nil {
		exitWithUsageError(err)
	}

	switch opts.Mode {
	case ModeHelpLong:
		fmt.Print(renderHelpLong(progName()))
		os.Exit(0)
	case ModeHelpShort:
		fmt.Print(renderHelpShort(progName()))
		os.Exit(0)
	case ModeVersion:
		fmt.Println(VersionString)
		os.Exit(0)
	case ModeManpage:
		fmt.Print(renderManpage())
		os.Exit(0)
	case ModeCompletions:
		out, ok := renderCompletions(opts.CompletionShell)
		if !ok {
			exitWithUsageError(fmt.Errorf("invalid value '%s' for '--print-completions <shell>'\n  [possible values: bash, elvish, fish, powershell, zsh]", opts.CompletionShell))
		}
		fmt.Print(out)
		os.Exit(0)
	}

	// Print version banner to stderr like the original does
	fmt.Fprintln(os.Stderr, VersionBanner)

	if opts.Path == "" {
		// No path provided
		if isStdinTTY() {
			logWarn("miniserve has been invoked without an explicit path so it will serve the current directory after a short delay.")
			logWarn("Invoke with -h|--help to see options or invoke as `miniserve .` to hide this advice.")
			for i := 3; i > 0; i-- {
				fmt.Fprintf(os.Stderr, "Starting server in %d…\r", i)
				time.Sleep(1 * time.Second)
			}
			fmt.Fprintln(os.Stderr)
			opts.Path = "."
		} else {
			logErr("Refusing to start as no explicit serve path was set and no interactive terminal was attached")
			logErr("Please set an explicit serve path like: `miniserve /my/path`")
			fmt.Fprintln(os.Stderr, "Error: Refusing to start as no explicit serve path was set and no interactive terminal was attached")
			fmt.Fprintln(os.Stderr, "Please set an explicit serve path like: `miniserve /my/path`")
			os.Exit(1)
		}
	}

	absPath, err := filepath.Abs(opts.Path)
	if err != nil {
		logErr("Failed to resolve path to be served")
		logErr(fmt.Sprintf("caused by: %s", err.Error()))
		fmt.Fprintln(os.Stderr, "Error: Failed to resolve path to be served")
		fmt.Fprintf(os.Stderr, "caused by: %s\n", err.Error())
		os.Exit(1)
	}

	// Check existence
	info, err := os.Stat(absPath)
	if err != nil {
		logErr("Failed to resolve path to be served")
		logErr(fmt.Sprintf("caused by: %s", errnoMessage(err)))
		fmt.Fprintln(os.Stderr, "Error: Failed to resolve path to be served")
		fmt.Fprintf(os.Stderr, "caused by: %s\n", errnoMessage(err))
		os.Exit(1)
	}

	if err := runServer(opts, absPath, info); err != nil {
		logErr(err.Error())
		os.Exit(1)
	}
}

func exitWithUsageError(err error) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", err.Error())
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}
