package main

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type Mode int

const (
	ModeServe Mode = iota
	ModeHelpLong
	ModeHelpShort
	ModeVersion
	ModeManpage
	ModeCompletions
)

type Options struct {
	Mode Mode

	Path string

	Verbose          bool
	TempDirectory    string
	Index            string
	SPA              bool
	PrettyURLs       bool
	Port             uint16
	Interfaces       []string
	Auth             []string
	AuthFile         string
	RoutePrefix      string
	RandomRoute      bool
	NoSymlinks       bool
	Hidden           bool
	SortingMethod    string
	SortingOrder     string
	ColorScheme      string
	ColorSchemeDark  string
	QRCode           bool
	UploadFiles      bool
	UploadDir        string
	WebUploadConc    uint64
	Chmod            string
	DirectorySize    bool
	Mkdir            bool
	MediaTypes       []string
	RawMediaType     string
	OnDuplicate      string
	RmFiles          bool
	RmDir            string
	EnableTar        bool
	EnableTarGz      bool
	EnableZip        bool
	CompressResponse bool
	DirsFirst        bool
	Title            string
	Headers          []string
	ShowSymlinkInfo  bool
	HideVersion      bool
	HideThemeSel     bool
	ShowWgetFooter   bool
	CompletionShell  string
	TLSCert          string
	TLSKey           string
	Readme           bool
	DisableIndex     bool
	EnableWebDav     bool
	SizeDisplay      string
	FileExternalURL  string
}

type argSpec struct {
	long     string  // long flag name (without --)
	short    rune    // short letter (0 if none)
	kind     argKind // type of argument
	envVar   string  // associated env var (optional)
	defValue string  // default value for help
	choices  []string
}

type argKind int

const (
	argBool argKind = iota
	argString
	argStringList
	argOptString // like --upload-files [<DIR>]
	argNumber
)

// argument list for parsing. Since order in --help is fixed we just enumerate them.
// We use a simple parser since the set of flags is closed.

func findArg(name string, specs []argSpec) (*argSpec, bool) {
	for i := range specs {
		if specs[i].long == name {
			return &specs[i], true
		}
	}
	return nil, false
}

func findShortArg(c rune, specs []argSpec) (*argSpec, bool) {
	for i := range specs {
		if specs[i].short == c {
			return &specs[i], true
		}
	}
	return nil, false
}

// The clap-style spec table for the miniserve CLI.
func argSpecs() []argSpec {
	return []argSpec{
		{long: "verbose", short: 'v', kind: argBool, envVar: "MINISERVE_VERBOSE"},
