func parseArgs(args []string) (*Options, error) {
	specs := argSpecs()
	opts := &Options{
		Port:            DefaultPort,
		SortingMethod:   "name",
		SortingOrder:    "desc",
		ColorScheme:     "squirrel",
		ColorSchemeDark: "archlinux",
		OnDuplicate:     "error",
		SizeDisplay:     "human",
		WebUploadConc:   0,
	}
	positional := []string{}
	i := 0
	doubleDashSeen := false

	setFromString := func(spec *argSpec, v string) error {
		return applyValue(opts, spec, v)
	}

	for i < len(args) {
		arg := args[i]
		if doubleDashSeen {
			positional = append(positional, arg)
			i++
			continue
		}
		if arg == "--" {
			doubleDashSeen = true
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			eq := strings.IndexByte(arg, '=')
			name := arg[2:]
			var val string
			var valProvided bool
			if eq >= 0 {
				name = arg[2:eq]
				val = arg[eq+1:]
				valProvided = true
			}
			spec, ok := findArg(name, specs)
			if !ok {
				return nil, fmt.Errorf("unexpected argument '--%s' found\n\n  tip: to pass '--%s' as a value, use '-- --%s'\n\nUsage: %s [OPTIONS] [PATH]", name, name, name, progName())
			}
			if spec.long == "help" {
				opts.Mode = ModeHelpLong
				return opts, nil
			}
			if spec.long == "version" {
				opts.Mode = ModeVersion
				return opts, nil
			}
			if spec.long == "print-manpage" {
				opts.Mode = ModeManpage
				return opts, nil
			}
			switch spec.kind {
			case argBool:
				if valProvided {
					return nil, fmt.Errorf("unexpected value '%s' for '--%s' found; no more were expected", val, name)
				}
				applyBool(opts, spec, true)
			case argOptString:
				if valProvided {
					if err := setFromString(spec, val); err != nil {
						return nil, err
					}
				} else {
					// Check next argument. If it starts with '-' it's treated as separate option.
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						// Still ambiguous; clap takes the next if it's not a flag-like? Actually for opt-args, clap requires = syntax. Let's not consume.
					}
					applyBool(opts, spec, true)
				}
			default:
				if !valProvided {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("a value is required for '--%s <%s>' but none was supplied", name, argName(spec))
					}
					i++
					val = args[i]
				}
				if err := setFromString(spec, val); err != nil {
					return nil, err
				}
				if spec.long == "print-completions" {
					opts.Mode = ModeCompletions
					opts.CompletionShell = val
					return opts, nil
				}
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flags; maybe bundled
			chars := []rune(arg[1:])
			consumedNext := false
			for ci := 0; ci < len(chars); ci++ {
				c := chars[ci]
				spec, ok := findShortArg(c, specs)
				if !ok {
					return nil, fmt.Errorf("unexpected argument '-%c' found\n\nUsage: %s [OPTIONS] [PATH]", c, progName())
				}
				if spec.long == "help" {
					opts.Mode = ModeHelpShort
					return opts, nil
				}
				if spec.long == "version" {
					opts.Mode = ModeVersion
					return opts, nil
				}
				switch spec.kind {
				case argBool:
					applyBool(opts, spec, true)
				case argOptString:
					// Check for attached value after the letter
					if ci+1 < len(chars) {
						val := string(chars[ci+1:])
						if err := setFromString(spec, val); err != nil {
							return nil, err
						}
						ci = len(chars) // break out
					} else {
						applyBool(opts, spec, true)
					}
				default:
					// Need a value
					var val string
					if ci+1 < len(chars) {
						val = string(chars[ci+1:])
						ci = len(chars)
					} else {
						if i+1 >= len(args) {
							return nil, fmt.Errorf("a value is required for '-%c <%s>' but none was supplied", c, argName(spec))
						}
						i++
						val = args[i]
						consumedNext = true
					}
					if err := setFromString(spec, val); err != nil {
						return nil, err
					}
					if spec.long == "print-completions" {
						opts.Mode = ModeCompletions
						opts.CompletionShell = val
						return opts, nil
					}
				}
			}
			_ = consumedNext
			i++
			continue
		}
		// Positional
		positional = append(positional, arg)
		i++
	}

	// Apply env vars for unset options
	if err := applyEnvVars(opts, specs); err != nil {
		return nil, err
	}

	if len(positional) > 1 {
		return nil, fmt.Errorf("unexpected argument '%s' found\n\nUsage: %s [OPTIONS] [PATH]", positional[1], progName())
	}
	if len(positional) == 1 {
		opts.Path = positional[0]
	} else if env := os.Getenv(MiniserveEnvKey); env != "" {
		opts.Path = env
	}

	return opts, nil
}

func argName(spec *argSpec) string {
	if spec.long == "port" {
		return "PORT"
	}
	upper := strings.ToUpper(strings.ReplaceAll(spec.long, "-", "_"))
	return upper
}

func applyBool(opts *Options, spec *argSpec, v bool) {
	switch spec.long {
	case "verbose":
		opts.Verbose = v
	case "spa":
		opts.SPA = v
	case "pretty-urls":
		opts.PrettyURLs = v
	case "random-route":
