	}
}

func applyValue(opts *Options, spec *argSpec, val string) error {
	// Validate choices where appropriate
	if len(spec.choices) > 0 && spec.kind != argStringList {
		if !containsStr(spec.choices, val) {
			return fmt.Errorf("invalid value '%s' for '--%s <%s>'\n  [possible values: %s]", val, spec.long, argName(spec), strings.Join(spec.choices, ", "))
		}
	}
	switch spec.long {
	case "temp-directory":
		opts.TempDirectory = val
	case "index":
		opts.Index = val
	case "port":
		n, err := strconv.ParseUint(val, 10, 16)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--port <PORT>': %s", val, numericErr(err))
		}
		opts.Port = uint16(n)
	case "interfaces":
		opts.Interfaces = append(opts.Interfaces, val)
	case "auth":
		if err := validateAuth(val); err != nil {
			return fmt.Errorf("invalid value '%s' for '--auth <AUTH>': %s", val, err.Error())
		}
		opts.Auth = append(opts.Auth, val)
	case "auth-file":
		opts.AuthFile = val
	case "route-prefix":
		opts.RoutePrefix = val
	case "default-sorting-method":
		opts.SortingMethod = val
	case "default-sorting-order":
		opts.SortingOrder = val
	case "color-scheme":
		opts.ColorScheme = val
	case "color-scheme-dark":
		opts.ColorSchemeDark = val
	case "upload-files":
		opts.UploadFiles = true
		opts.UploadDir = val
	case "web-upload-files-concurrency":
		n, err := strconv.ParseUint(val, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--web-upload-files-concurrency <WEB_UPLOAD_CONCURRENCY>': %s", val, numericErr(err))
		}
		opts.WebUploadConc = n
	case "chmod":
		if _, err := strconv.ParseUint(val, 8, 32); err != nil {
			return fmt.Errorf("invalid value '%s' for '--chmod <CHMOD>': %s", val, numericErr(err))
		}
		opts.Chmod = val
	case "media-type":
		opts.MediaTypes = append(opts.MediaTypes, val)
	case "raw-media-type":
		opts.RawMediaType = val
	case "on-duplicate-files":
		opts.OnDuplicate = val
	case "rm-files":
		opts.RmFiles = true
		opts.RmDir = val
	case "title":
		opts.Title = val
	case "header":
		opts.Headers = append(opts.Headers, val)
	case "print-completions":
		opts.CompletionShell = val
	case "tls-cert":
		opts.TLSCert = val
	case "tls-key":
		opts.TLSKey = val
	case "size-display":
		opts.SizeDisplay = val
	case "file-external-url":
		opts.FileExternalURL = val
	}
	return nil
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func numericErr(err error) string {
	// Emulate Rust-like error
	if errors.Is(err, strconv.ErrSyntax) {
		return "invalid digit found in string"
	}
	if errors.Is(err, strconv.ErrRange) {
		return "number too large to fit in target type"
	}
	return err.Error()
}

func validateAuth(s string) error {
	// Format: username:password OR username:sha256:<hex> OR username:sha512:<hex>
	idx := strings.IndexByte(s, ':')
	if idx < 0 {
		return errors.New("Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash")
	}
	rest := s[idx+1:]
	if strings.HasPrefix(rest, "sha256:") {
		hash := rest[len("sha256:"):]
		if !isHex(hash) || len(hash) != 64 {
			return errors.New("Invalid format for password hash. Expected hex code")
		}
	} else if strings.HasPrefix(rest, "sha512:") {
		hash := rest[len("sha512:"):]
		if !isHex(hash) || len(hash) != 128 {
			return errors.New("Invalid format for password hash. Expected hex code")
		}
	}
	return nil
}

func isHex(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return false
		}
	}
	return true
}

func applyEnvVars(opts *Options, specs []argSpec) error {
	// Only apply if we haven't already set via CLI — but for simplicity, apply only when the option is zero-valued.
	for _, spec := range specs {
		if spec.envVar == "" {
			continue
		}
		v := os.Getenv(spec.envVar)
		if v == "" {
			continue
		}
		switch spec.long {
		case "verbose":
			if !opts.Verbose {
				opts.Verbose = parseBoolish(v)
			}
		case "spa":
			if !opts.SPA {
				opts.SPA = parseBoolish(v)
			}
		case "pretty-urls":
			if !opts.PrettyURLs {
				opts.PrettyURLs = parseBoolish(v)
			}
		case "random-route":
			if !opts.RandomRoute {
				opts.RandomRoute = parseBoolish(v)
			}
		case "no-symlinks":
			if !opts.NoSymlinks {
				opts.NoSymlinks = parseBoolish(v)
			}
		case "hidden":
			if !opts.Hidden {
				opts.Hidden = parseBoolish(v)
			}
		case "qrcode":
			if !opts.QRCode {
				opts.QRCode = parseBoolish(v)
			}
		case "directory-size":
			if !opts.DirectorySize {
				opts.DirectorySize = parseBoolish(v)
			}
		case "mkdir":
			if !opts.Mkdir {
				opts.Mkdir = parseBoolish(v)
			}
		case "enable-tar":
			if !opts.EnableTar {
				opts.EnableTar = parseBoolish(v)
			}
		case "enable-tar-gz":
			if !opts.EnableTarGz {
				opts.EnableTarGz = parseBoolish(v)
			}
		case "enable-zip":
			if !opts.EnableZip {
				opts.EnableZip = parseBoolish(v)
			}
		case "compress-response":
			if !opts.CompressResponse {
				opts.CompressResponse = parseBoolish(v)
			}
		case "dirs-first":
			if !opts.DirsFirst {
				opts.DirsFirst = parseBoolish(v)
			}
		case "show-symlink-info":
			if !opts.ShowSymlinkInfo {
				opts.ShowSymlinkInfo = parseBoolish(v)
			}
		case "hide-version-footer":
			if !opts.HideVersion {
				opts.HideVersion = parseBoolish(v)
			}
		case "hide-theme-selector":
			if !opts.HideThemeSel {
				opts.HideThemeSel = parseBoolish(v)
			}
		case "show-wget-footer":
			if !opts.ShowWgetFooter {
				opts.ShowWgetFooter = parseBoolish(v)
			}
		case "readme":
			if !opts.Readme {
				opts.Readme = parseBoolish(v)
			}
		case "disable-indexing":
			if !opts.DisableIndex {
				opts.DisableIndex = parseBoolish(v)
			}
		case "enable-webdav":
			if !opts.EnableWebDav {
				opts.EnableWebDav = parseBoolish(v)
			}
		case "port":
			if opts.Port == DefaultPort {
				n, err := strconv.ParseUint(v, 10, 16)
				if err != nil {
					return fmt.Errorf("invalid value '%s' for '--port <PORT>': %s", v, numericErr(err))
				}
				opts.Port = uint16(n)
			}
		case "interfaces":
			if len(opts.Interfaces) == 0 {
				opts.Interfaces = append(opts.Interfaces, v)
			}
		case "temp-directory":
			if opts.TempDirectory == "" {
				opts.TempDirectory = v
			}
		case "index":
			if opts.Index == "" {
				opts.Index = v
			}
		case "auth":
			if len(opts.Auth) == 0 {
				if err := validateAuth(v); err == nil {
					opts.Auth = append(opts.Auth, v)
				}
			}
		case "auth-file":
			if opts.AuthFile == "" {
				opts.AuthFile = v
			}
		case "route-prefix":
			if opts.RoutePrefix == "" {
				opts.RoutePrefix = v
			}
		case "default-sorting-method":
			if opts.SortingMethod == "name" {
				opts.SortingMethod = v
			}
		case "default-sorting-order":
			if opts.SortingOrder == "desc" {
				opts.SortingOrder = v
			}
		case "color-scheme":
			if opts.ColorScheme == "squirrel" {
				opts.ColorScheme = v
			}
		case "color-scheme-dark":
			if opts.ColorSchemeDark == "archlinux" {
				opts.ColorSchemeDark = v
			}
		case "upload-files":
			if !opts.UploadFiles {
				opts.UploadFiles = true
				opts.UploadDir = v
			}
		case "web-upload-files-concurrency":
			if opts.WebUploadConc == 0 {
				if n, err := strconv.ParseUint(v, 10, 64); err == nil {
					opts.WebUploadConc = n
				}
			}
		case "chmod":
			if opts.Chmod == "" {
				opts.Chmod = v
			}
		case "raw-media-type":
			if opts.RawMediaType == "" {
				opts.RawMediaType = v
			}
		case "on-duplicate-files":
			if opts.OnDuplicate == "error" {
				opts.OnDuplicate = v
			}
		case "rm-files":
			if !opts.RmFiles {
				opts.RmFiles = true
				opts.RmDir = v
			}
		case "title":
			if opts.Title == "" {
				opts.Title = v
			}
		case "header":
			if len(opts.Headers) == 0 {
				opts.Headers = append(opts.Headers, v)
			}
		case "tls-cert":
			if opts.TLSCert == "" {
				opts.TLSCert = v
			}
		case "tls-key":
			if opts.TLSKey == "" {
				opts.TLSKey = v
			}
		case "size-display":
			if opts.SizeDisplay == "human" {
				opts.SizeDisplay = v
			}
		case "file-external-url":
			if opts.FileExternalURL == "" {
				opts.FileExternalURL = v
			}
		}
	}
	return nil
}

func parseBoolish(v string) bool {
	switch strings.ToLower(v) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}
