func parseArgs(args []string) (*Options, error) {
	specs := argSpecs()
	opts := &Options{
		Port:            DefaultPort,
		SortingMethod:   "name",
		SortingOrder:    "desc",
		ColorScheme:     "squirrel",
		ColorSchemeDark: "archlinux",
		OnDuplicate:     "error",
		SizeDisplay:     "human",
		WebUploadConc:   0,
	}
	positional := []string{}
	i := 0
	doubleDashSeen := false

	setFromString := func(spec *argSpec, v string) error {
		return applyValue(opts, spec, v)
	}

	for i < len(args) {
		arg := args[i]
		if doubleDashSeen {
			positional = append(positional, arg)
			i++
			continue
		}
		if arg == "--" {
			doubleDashSeen = true
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			eq := strings.IndexByte(arg, '=')
			name := arg[2:]
			var val string
			var valProvided bool
			if eq >= 0 {
				name = arg[2:eq]
				val = arg[eq+1:]
				valProvided = true
			}
			spec, ok := findArg(name, specs)
			if !ok {
				return nil, fmt.Errorf("unexpected argument '--%s' found\n\n  tip: to pass '--%s' as a value, use '-- --%s'\n\nUsage: %s [OPTIONS] [PATH]", name, name, name, progName())
			}
			if spec.long == "help" {
				opts.Mode = ModeHelpLong
				return opts, nil
			}
			if spec.long == "version" {
				opts.Mode = ModeVersion
				return opts, nil
			}
			if spec.long == "print-manpage" {
				opts.Mode = ModeManpage
				return opts, nil
			}
			switch spec.kind {
			case argBool:
				if valProvided {
					return nil, fmt.Errorf("unexpected value '%s' for '--%s' found; no more were expected", val, name)
				}
				applyBool(opts, spec, true)
			case argOptString:
				if valProvided {
					if err := setFromString(spec, val); err != nil {
						return nil, err
					}
				} else {
					// Check next argument. If it starts with '-' it's treated as separate option.
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						// Still ambiguous; clap takes the next if it's not a flag-like? Actually for opt-args, clap requires = syntax. Let's not consume.
					}
					applyBool(opts, spec, true)
				}
			default:
				if !valProvided {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("a value is required for '--%s <%s>' but none was supplied", name, argName(spec))
					}
					i++
					val = args[i]
				}
				if err := setFromString(spec, val); err != nil {
					return nil, err
				}
				if spec.long == "print-completions" {
					opts.Mode = ModeCompletions
					opts.CompletionShell = val
					return opts, nil
				}
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flags; maybe bundled
			chars := []rune(arg[1:])
			consumedNext := false
			for ci := 0; ci < len(chars); ci++ {
				c := chars[ci]
				spec, ok := findShortArg(c, specs)
				if !ok {
					return nil, fmt.Errorf("unexpected argument '-%c' found\n\nUsage: %s [OPTIONS] [PATH]", c, progName())
				}
				if spec.long == "help" {
					opts.Mode = ModeHelpShort
					return opts, nil
				}
				if spec.long == "version" {
					opts.Mode = ModeVersion
					return opts, nil
				}
				switch spec.kind {
				case argBool:
					applyBool(opts, spec, true)
				case argOptString:
					// Check for attached value after the letter
					if ci+1 < len(chars) {
						val := string(chars[ci+1:])
						if err := setFromString(spec, val); err != nil {
							return nil, err
						}
						ci = len(chars) // break out
					} else {
						applyBool(opts, spec, true)
					}
				default:
					// Need a value
					var val string
					if ci+1 < len(chars) {
						val = string(chars[ci+1:])
						ci = len(chars)
					} else {
						if i+1 >= len(args) {
							return nil, fmt.Errorf("a value is required for '-%c <%s>' but none was supplied", c, argName(spec))
						}
						i++
						val = args[i]
						consumedNext = true
					}
					if err := setFromString(spec, val); err != nil {
						return nil, err
					}
					if spec.long == "print-completions" {
						opts.Mode = ModeCompletions
						opts.CompletionShell = val
						return opts, nil
					}
				}
			}
			_ = consumedNext
			i++
			continue
		}
		// Positional
		positional = append(positional, arg)
		i++
	}

	// Apply env vars for unset options
	if err := applyEnvVars(opts, specs); err != nil {
		return nil, err
	}

	if len(positional) > 1 {
		return nil, fmt.Errorf("unexpected argument '%s' found\n\nUsage: %s [OPTIONS] [PATH]", positional[1], progName())
	}
	if len(positional) == 1 {
		opts.Path = positional[0]
	} else if env := os.Getenv(MiniserveEnvKey); env != "" {
		opts.Path = env
	}

	return opts, nil
}

func argName(spec *argSpec) string {
	if spec.long == "port" {
		return "PORT"
	}
	upper := strings.ToUpper(strings.ReplaceAll(spec.long, "-", "_"))
	return upper
}

func applyBool(opts *Options, spec *argSpec, v bool) {
	switch spec.long {
	case "verbose":
		opts.Verbose = v
	case "spa":
		opts.SPA = v
	case "pretty-urls":
		opts.PrettyURLs = v
	case "random-route":
		opts.RandomRoute = v
	case "no-symlinks":
		opts.NoSymlinks = v
	case "hidden":
		opts.Hidden = v
	case "qrcode":
		opts.QRCode = v
	case "upload-files":
		opts.UploadFiles = v
	case "directory-size":
		opts.DirectorySize = v
	case "mkdir":
		opts.Mkdir = v
	case "rm-files":
		opts.RmFiles = v
	case "enable-tar":
		opts.EnableTar = v
	case "enable-tar-gz":
		opts.EnableTarGz = v
	case "enable-zip":
		opts.EnableZip = v
	case "compress-response":
		opts.CompressResponse = v
	case "dirs-first":
		opts.DirsFirst = v
	case "show-symlink-info":
		opts.ShowSymlinkInfo = v
	case "hide-version-footer":
		opts.HideVersion = v
	case "hide-theme-selector":
		opts.HideThemeSel = v
	case "show-wget-footer":
		opts.ShowWgetFooter = v
	case "readme":
		opts.Readme = v
	case "disable-indexing":
		opts.DisableIndex = v
	case "enable-webdav":
		opts.EnableWebDav = v
	}
}

func applyValue(opts *Options, spec *argSpec, val string) error {
	// Validate choices where appropriate
	if len(spec.choices) > 0 && spec.kind != argStringList {
		if !containsStr(spec.choices, val) {
			return fmt.Errorf("invalid value '%s' for '--%s <%s>'\n  [possible values: %s]", val, spec.long, argName(spec), strings.Join(spec.choices, ", "))
		}
	}
	switch spec.long {
	case "temp-directory":
		opts.TempDirectory = val
	case "index":
		opts.Index = val
	case "port":
		n, err := strconv.ParseUint(val, 10, 16)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--port <PORT>': %s", val, numericErr(err))
		}
		opts.Port = uint16(n)
	case "interfaces":
		opts.Interfaces = append(opts.Interfaces, val)
	case "auth":
		if err := validateAuth(val); err != nil {
			return fmt.Errorf("invalid value '%s' for '--auth <AUTH>': %s", val, err.Error())
		}
		opts.Auth = append(opts.Auth, val)
	case "auth-file":
		opts.AuthFile = val
	case "route-prefix":
		opts.RoutePrefix = val
	case "default-sorting-method":
		opts.SortingMethod = val
	case "default-sorting-order":
		opts.SortingOrder = val
	case "color-scheme":
		opts.ColorScheme = val
	case "color-scheme-dark":
		opts.ColorSchemeDark = val
	case "upload-files":
		opts.UploadFiles = true
		opts.UploadDir = val
	case "web-upload-files-concurrency":
		n, err := strconv.ParseUint(val, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--web-upload-files-concurrency <WEB_UPLOAD_CONCURRENCY>': %s", val, numericErr(err))
		}
		opts.WebUploadConc = n
	case "chmod":
		if _, err := strconv.ParseUint(val, 8, 32); err != nil {
			return fmt.Errorf("invalid value '%s' for '--chmod <CHMOD>': %s", val, numericErr(err))
		}
		opts.Chmod = val
	case "media-type":
		opts.MediaTypes = append(opts.MediaTypes, val)
	case "raw-media-type":
		opts.RawMediaType = val
	case "on-duplicate-files":
		opts.OnDuplicate = val
	case "rm-files":
		opts.RmFiles = true
		opts.RmDir = val
	case "title":
		opts.Title = val
	case "header":
		opts.Headers = append(opts.Headers, val)
	case "print-completions":
		opts.CompletionShell = val
	case "tls-cert":
		opts.TLSCert = val
	case "tls-key":
		opts.TLSKey = val
	case "size-display":
		opts.SizeDisplay = val
	case "file-external-url":
		opts.FileExternalURL = val
	}
	return nil
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func numericErr(err error) string {
	// Emulate Rust-like error
	if errors.Is(err, strconv.ErrSyntax) {
		return "invalid digit found in string"
	}
	if errors.Is(err, strconv.ErrRange) {
		return "number too large to fit in target type"
	}
	return err.Error()
}

func validateAuth(s string) error {
	// Format: username:password OR username:sha256:<hex> OR username:sha512:<hex>
	idx := strings.IndexByte(s, ':')
	if idx < 0 {
		return errors.New("Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash")
	}
	rest := s[idx+1:]
	if strings.HasPrefix(rest, "sha256:") {
		hash := rest[len("sha256:"):]
		if !isHex(hash) || len(hash) != 64 {
			return errors.New("Invalid format for password hash. Expected hex code")
		}
	} else if strings.HasPrefix(rest, "sha512:") {
		hash := rest[len("sha512:"):]
		if !isHex(hash) || len(hash) != 128 {
			return errors.New("Invalid format for password hash. Expected hex code")
		}
	}
	return nil
}

func isHex(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return false
		}
	}
	return true
}

func applyEnvVars(opts *Options, specs []argSpec) error {
	// Only apply if we haven't already set via CLI — but for simplicity, apply only when the option is zero-valued.
	for _, spec := range specs {
		if spec.envVar == "" {
			continue
		}
		v := os.Getenv(spec.envVar)
		if v == "" {
			continue
		}
		switch spec.long {
		case "verbose":
			if !opts.Verbose {
				opts.Verbose = parseBoolish(v)
			}
		case "spa":
			if !opts.SPA {
				opts.SPA = parseBoolish(v)
			}
		case "pretty-urls":
			if !opts.PrettyURLs {
				opts.PrettyURLs = parseBoolish(v)
			}
		case "random-route":
			if !opts.RandomRoute {
				opts.RandomRoute = parseBoolish(v)
			}
		case "no-symlinks":
			if !opts.NoSymlinks {
				opts.NoSymlinks = parseBoolish(v)
			}
		case "hidden":
			if !opts.Hidden {
				opts.Hidden = parseBoolish(v)
			}
		case "qrcode":
			if !opts.QRCode {
				opts.QRCode = parseBoolish(v)
			}
		case "directory-size":
			if !opts.DirectorySize {
				opts.DirectorySize = parseBoolish(v)
			}
		case "mkdir":
			if !opts.Mkdir {
				opts.Mkdir = parseBoolish(v)
			}
		case "enable-tar":
			if !opts.EnableTar {
				opts.EnableTar = parseBoolish(v)
			}
		case "enable-tar-gz":
			if !opts.EnableTarGz {
				opts.EnableTarGz = parseBoolish(v)
			}
		case "enable-zip":
			if !opts.EnableZip {
				opts.EnableZip = parseBoolish(v)
			}
		case "compress-response":
			if !opts.CompressResponse {
				opts.CompressResponse = parseBoolish(v)
			}
		case "dirs-first":
			if !opts.DirsFirst {
				opts.DirsFirst = parseBoolish(v)
			}
		case "show-symlink-info":
			if !opts.ShowSymlinkInfo {
				opts.ShowSymlinkInfo = parseBoolish(v)
			}
		case "hide-version-footer":
			if !opts.HideVersion {
				opts.HideVersion = parseBoolish(v)
			}
		case "hide-theme-selector":
			if !opts.HideThemeSel {
				opts.HideThemeSel = parseBoolish(v)
			}
		case "show-wget-footer":
			if !opts.ShowWgetFooter {
				opts.ShowWgetFooter = parseBoolish(v)
			}
		case "readme":
			if !opts.Readme {
				opts.Readme = parseBoolish(v)
			}
		case "disable-indexing":
			if !opts.DisableIndex {
				opts.DisableIndex = parseBoolish(v)
			}
		case "enable-webdav":
			if !opts.EnableWebDav {
				opts.EnableWebDav = parseBoolish(v)
			}
		case "port":
			if opts.Port == DefaultPort {
				n, err := strconv.ParseUint(v, 10, 16)
				if err != nil {
					return fmt.Errorf("invalid value '%s' for '--port <PORT>': %s", v, numericErr(err))
				}
				opts.Port = uint16(n)
			}
		case "interfaces":
			if len(opts.Interfaces) == 0 {
				opts.Interfaces = append(opts.Interfaces, v)
			}
		case "temp-directory":
			if opts.TempDirectory == "" {
				opts.TempDirectory = v
			}
		case "index":
			if opts.Index == "" {
				opts.Index = v
			}
		case "auth":
			if len(opts.Auth) == 0 {
				if err := validateAuth(v); err == nil {
					opts.Auth = append(opts.Auth, v)
				}
			}
		case "auth-file":
			if opts.AuthFile == "" {
				opts.AuthFile = v
			}
		case "route-prefix":
			if opts.RoutePrefix == "" {
				opts.RoutePrefix = v
			}
		case "default-sorting-method":
			if opts.SortingMethod == "name" {
				opts.SortingMethod = v
			}
		case "default-sorting-order":
			if opts.SortingOrder == "desc" {
				opts.SortingOrder = v
			}
		case "color-scheme":
			if opts.ColorScheme == "squirrel" {
				opts.ColorScheme = v
			}
		case "color-scheme-dark":
			if opts.ColorSchemeDark == "archlinux" {
				opts.ColorSchemeDark = v
			}
		case "upload-files":
			if !opts.UploadFiles {
				opts.UploadFiles = true
				opts.UploadDir = v
			}
		case "web-upload-files-concurrency":
			if opts.WebUploadConc == 0 {
				if n, err := strconv.ParseUint(v, 10, 64); err == nil {
					opts.WebUploadConc = n
				}
			}
		case "chmod":
			if opts.Chmod == "" {
				opts.Chmod = v
			}
		case "raw-media-type":
			if opts.RawMediaType == "" {
				opts.RawMediaType = v
			}
		case "on-duplicate-files":
			if opts.OnDuplicate == "error" {
				opts.OnDuplicate = v
			}
		case "rm-files":
			if !opts.RmFiles {
				opts.RmFiles = true
				opts.RmDir = v
			}
		case "title":
			if opts.Title == "" {
				opts.Title = v
			}
		case "header":
			if len(opts.Headers) == 0 {
				opts.Headers = append(opts.Headers, v)
			}
		case "tls-cert":
			if opts.TLSCert == "" {
				opts.TLSCert = v
			}
		case "tls-key":
			if opts.TLSKey == "" {
				opts.TLSKey = v
			}
		case "size-display":
			if opts.SizeDisplay == "human" {
				opts.SizeDisplay = v
			}
		case "file-external-url":
			if opts.FileExternalURL == "" {
				opts.FileExternalURL = v
			}
		}
	}
	return nil
}

func parseBoolish(v string) bool {
	switch strings.ToLower(v) {
	case "1", "true", "yes", "on":
		return true
	default:
		return false
	}
}
