package main

import (
	"os"
	"syscall"
	"unsafe"
)

func isStdinTTY() bool {
	fd := os.Stdin.Fd()
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(
		syscall.SYS_IOCTL,
		fd,
		syscall.TCGETS,
		uintptr(unsafe.Pointer(&termios)),
		0, 0, 0,
	)
	return err == 0
}

func errnoMessage(err error) string {
	// Unwrap PathError if applicable
	if pe, ok := err.(*os.PathError); ok {
		if errno, ok := pe.Err.(syscall.Errno); ok {
			return osErrorString(errno)
		}
	}
	return err.Error()
}

func osErrorString(errno syscall.Errno) string {
	switch errno {
	case syscall.ENOENT:
		return "No such file or directory (os error 2)"
	case syscall.EACCES:
		return "Permission denied (os error 13)"
	case syscall.ENOTDIR:
		return "Not a directory (os error 20)"
	default:
		return errno.Error() + " (os error " + itoa(int(errno)) + ")"
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}
