package main

import (
	"fmt"
	"html"
	"io"
	"mime"
	"net"
	"net/http"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

type serverState struct {
	opts       *Options
	servePath  string
	isFile     bool
	fileBase   string
}

func runServer(opts *Options, absPath string, info os.FileInfo) error {
	st := &serverState{opts: opts, servePath: absPath, isFile: !info.IsDir(), fileBase: filepath.Base(absPath)}

	interfaces := opts.Interfaces
	if len(interfaces) == 0 {
		interfaces = []string{"::", "0.0.0.0"}
	}

	// Bind to interface(s).
	listeners := make([]net.Listener, 0, len(interfaces))
	bindLabels := []string{}
	for _, iface := range interfaces {
		addr := net.JoinHostPort(iface, strconv.Itoa(int(opts.Port)))
		l, err := net.Listen("tcp", addr)
		if err != nil {
			// Close any already-opened
			for _, done := range listeners {
				done.Close()
			}
			return fmt.Errorf("failed to bind to %s: %w", addr, err)
		}
		listeners = append(listeners, l)
		bindLabels = append(bindLabels, addr)
	}

	scheme := "http"
	if opts.TLSCert != "" && opts.TLSKey != "" {
		scheme = "https"
	}

	fmt.Fprintf(os.Stderr, "Bound to %s\n", strings.Join(bindLabels, ", "))
	fmt.Fprintf(os.Stderr, "Serving path %s\n", absPath)
	fmt.Fprintln(os.Stderr, "Available at (non-exhaustive list):")
	for _, addr := range availableAddresses(interfaces, opts.Port, scheme) {
		fmt.Fprintf(os.Stderr, "    %s\n", addr)
	}
	fmt.Fprintln(os.Stderr)

	// Start each listener in a goroutine.
	errCh := make(chan error, len(listeners))
	for _, l := range listeners {
		go func(l net.Listener) {
			srv := &http.Server{
				Handler: st.handler(),
			}
			errCh <- srv.Serve(l)
		}(l)
	}
	return <-errCh
}

func availableAddresses(interfaces []string, port uint16, scheme string) []string {
	addrSet := map[string]struct{}{}
	for _, iface := range interfaces {
		if iface == "0.0.0.0" || iface == "::" {
			// Enumerate local interfaces
			addrs, err := net.InterfaceAddrs()
			if err == nil {
				for _, a := range addrs {
					host := ""
					switch v := a.(type) {
					case *net.IPNet:
						host = v.IP.String()
					case *net.IPAddr:
						host = v.IP.String()
					}
					if host == "" {
						continue
					}
					if iface == "0.0.0.0" && !strings.Contains(host, ":") {
						addrSet[fmt.Sprintf("%s://%s:%d", scheme, host, port)] = struct{}{}
					}
					if iface == "::" && strings.Contains(host, ":") {
						addrSet[fmt.Sprintf("%s://[%s]:%d", scheme, stripZone(host), port)] = struct{}{}
					}
					if iface == "::" && !strings.Contains(host, ":") {
						addrSet[fmt.Sprintf("%s://%s:%d", scheme, host, port)] = struct{}{}
					}
				}
			}
		} else {
			if strings.Contains(iface, ":") {
				addrSet[fmt.Sprintf("%s://[%s]:%d", scheme, iface, port)] = struct{}{}
			} else {
				addrSet[fmt.Sprintf("%s://%s:%d", scheme, iface, port)] = struct{}{}
			}
		}
	}
	out := make([]string, 0, len(addrSet))
	for a := range addrSet {
		out = append(out, a)
	}
	sort.Strings(out)
	return out
}

func stripZone(h string) string {
	i := strings.Index(h, "%")
	if i < 0 {
		return h
	}
	return h[:i]
}

func (s *serverState) handler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		s.serveHTTP(w, r)
	})
}

func (s *serverState) serveHTTP(w http.ResponseWriter, r *http.Request) {
	if s.opts.Verbose {
		logInfo(fmt.Sprintf("%s %s", r.Method, r.URL.Path))
	}

	// Apply custom headers
	for _, h := range s.opts.Headers {
		idx := strings.IndexByte(h, ':')
		if idx < 0 {
			continue
		}
		name := strings.TrimSpace(h[:idx])
		val := strings.TrimSpace(h[idx+1:])
		if name != "" {
			w.Header().Set(name, val)
		}
	}

	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if s.isFile {
		// Serve single file
		f, err := os.Open(s.servePath)
		if err != nil {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
		defer f.Close()
		fi, err := f.Stat()
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		http.ServeContent(w, r, s.fileBase, fi.ModTime(), f)
		return
	}

	urlPath := r.URL.Path
	// URL-decode
	decoded, err := url.PathUnescape(urlPath)
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	clean := path.Clean(decoded)
	if strings.HasPrefix(clean, "..") {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	target := filepath.Join(s.servePath, filepath.FromSlash(clean))
	fi, err := os.Stat(target)
	if err != nil {
		logErr(fmt.Sprintf("Route %s could not be found", r.URL.Path))
		writeNotFound(w, r)
		return
	}
	if fi.IsDir() {
		// Index file?
		if s.opts.Index != "" {
			idx := filepath.Join(target, s.opts.Index)
			if ifi, err := os.Stat(idx); err == nil && !ifi.IsDir() {
				http.ServeFile(w, r, idx)
				return
			}
		}
		// Ensure trailing slash
		if !strings.HasSuffix(r.URL.Path, "/") {
			http.Redirect(w, r, r.URL.Path+"/", http.StatusTemporaryRedirect)
			return
		}
		if s.opts.DisableIndex {
			http.Error(w, "indexing disabled", http.StatusForbidden)
			return
		}
		writeDirectoryListing(w, r, s.opts, target, decoded)
		return
	}
	// File
	ctype := mime.TypeByExtension(filepath.Ext(target))
	if ctype != "" {
		w.Header().Set("Content-Type", ctype)
	}
	http.ServeFile(w, r, target)
}

func writeNotFound(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html")
	w.WriteHeader(http.StatusNotFound)
	fmt.Fprintf(w, "<!DOCTYPE html><html><head><title>404 Not Found</title></head><body><h1>404 Not Found</h1><p>The requested resource <code>%s</code> could not be found.</p></body></html>", html.EscapeString(r.URL.Path))
}

func writeDirectoryListing(w http.ResponseWriter, r *http.Request, opts *Options, dirPath, urlPath string) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	type ent struct {
		Name string
		IsDir bool
		Size int64
		Mod  time.Time
	}
	list := make([]ent, 0, len(entries))
	for _, e := range entries {
		name := e.Name()
		if !opts.Hidden && strings.HasPrefix(name, ".") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		// Skip symlinks if no-symlinks set
		if opts.NoSymlinks && info.Mode()&os.ModeSymlink != 0 {
			continue
		}
		list = append(list, ent{Name: name, IsDir: e.IsDir(), Size: info.Size(), Mod: info.ModTime()})
	}
	// Sort by name ascending
	sort.Slice(list, func(i, j int) bool {
		if opts.DirsFirst && list[i].IsDir != list[j].IsDir {
			return list[i].IsDir
		}
		switch opts.SortingMethod {
		case "size":
			if list[i].Size == list[j].Size {
				return list[i].Name < list[j].Name
			}
			if opts.SortingOrder == "asc" {
				return list[i].Size < list[j].Size
			}
			return list[i].Size > list[j].Size
		case "date":
			if list[i].Mod.Equal(list[j].Mod) {
				return list[i].Name < list[j].Name
			}
			if opts.SortingOrder == "asc" {
				return list[i].Mod.Before(list[j].Mod)
			}
			return list[i].Mod.After(list[j].Mod)
		default:
			if opts.SortingOrder == "asc" {
				return list[i].Name < list[j].Name
			}
			return list[i].Name > list[j].Name
		}
	})

	title := opts.Title
	if title == "" {
		title = r.Host
	}

	var b strings.Builder
	b.WriteString("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>")
	b.WriteString(html.EscapeString(title))
	b.WriteString("</title><style>body{font-family:sans-serif;margin:2em;}table{border-collapse:collapse;width:100%;}th,td{border-bottom:1px solid #ddd;padding:0.4em 0.6em;text-align:left;}a{text-decoration:none;color:#006;}a:hover{text-decoration:underline;}</style></head><body>")
	b.WriteString("<h1>")
	b.WriteString(html.EscapeString(title))
	b.WriteString(html.EscapeString(urlPath))
	b.WriteString("</h1>")
	b.WriteString("<table><thead><tr><th>Name</th><th>Size</th><th>Last modification</th></tr></thead><tbody>")
	if urlPath != "/" {
		b.WriteString("<tr><td><a href=\"..\">..</a></td><td></td><td></td></tr>")
	}
