				return list[i].Mod.Before(list[j].Mod)
			}
			return list[i].Mod.After(list[j].Mod)
		default:
			if opts.SortingOrder == "asc" {
				return list[i].Name < list[j].Name
			}
			return list[i].Name > list[j].Name
		}
	})

	title := opts.Title
	if title == "" {
		title = r.Host
	}

	var b strings.Builder
	b.WriteString("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>")
	b.WriteString(html.EscapeString(title))
	b.WriteString("</title><style>body{font-family:sans-serif;margin:2em;}table{border-collapse:collapse;width:100%;}th,td{border-bottom:1px solid #ddd;padding:0.4em 0.6em;text-align:left;}a{text-decoration:none;color:#006;}a:hover{text-decoration:underline;}</style></head><body>")
	b.WriteString("<h1>")
	b.WriteString(html.EscapeString(title))
	b.WriteString(html.EscapeString(urlPath))
	b.WriteString("</h1>")
	b.WriteString("<table><thead><tr><th>Name</th><th>Size</th><th>Last modification</th></tr></thead><tbody>")
	if urlPath != "/" {
		b.WriteString("<tr><td><a href=\"..\">..</a></td><td></td><td></td></tr>")
	}
	for _, e := range list {
		name := e.Name
		link := url.PathEscape(name)
		if e.IsDir {
			name += "/"
			link += "/"
		}
		b.WriteString("<tr><td><a href=\"")
		b.WriteString(link)
		b.WriteString("\">")
		b.WriteString(html.EscapeString(name))
		b.WriteString("</a></td><td>")
		if !e.IsDir {
			b.WriteString(humanSize(e.Size))
		}
		b.WriteString("</td><td>")
		b.WriteString(e.Mod.UTC().Format("2006-01-02 15:04:05 -07:00"))
		b.WriteString("</td></tr>")
	}
	b.WriteString("</tbody></table>")
	if !opts.HideVersion {
		b.WriteString("<footer><small>Served by miniserve v0.32.0</small></footer>")
	}
	b.WriteString("</body></html>")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	io.WriteString(w, b.String())
}

